ListNode* dummy = new ListNode(0);
ListNode* current = dummy;
while (l1 && l2) {
    if (l1->val < l2->val) {
        current->next = l1;
        l1 = l1->next;
    } else {
        current->next = l2;
        l2 = l2->next;
    }
    current = current->next;
}
if (l1) {
    current->next = l1;
} else if (l2) {
    current->next = l2;
}
ListNode* result = dummy->next;
delete dummy;
return result;

